async function renderInsights(){const h=$('insightsContent');if(!signedIn()){h.innerHTML='<div class="empty">Sign in to build your profile.</div>';return}const s=todayMinus(7),[e,qz,m,sess,p]=await Promise.all([q('learning_events',{eq:{user_id:uid()},gte:{occurred_at:s},order:'occurred_at',asc:false}),q('quiz_attempts',{eq:{user_id:uid()},gte:{started_at:s},not:{completed_at:null}}),q('concept_mastery',{eq:{user_id:uid()},order:'mastery',asc:true,limit:20}),q('reading_sessions',{eq:{user_id:uid()},gte:{started_at:s},not:{ended_at:null}}),q('learning_patterns',{eq:{user_id:uid()},eq:{active:true},limit:12})]),focus=sess.reduce((a,z)=>a+Number(z.active_seconds||0),0),scores=qz.map(z=>100*Number(z.score||0)/Math.max(1,Number(z.max_score||100))),avg=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0,avgM=m.length?Math.round(m.reduce((a,b)=>a+Number(b.mastery||0),0)/m.length):0,days=new Set(e.map(x=>x.occurred_at.slice(0,10))).size;h.innerHTML='<div class="grid g4">'+[['Focused',fmtMinutes(focus)],['Pages',new Set(e.filter(x=>x.event_type==='page_entered').map(x=>x.resource_id+'-'+x.payload?.page)).size],['Recall',avg+'%'],['Active days',days+'/7']].map(x=>'<div class="card metric"><div class="metric-label">'+x[0]+'</div><div class="metric-value">'+x[1]+'</div></div>').join('')+'</div><div class="grid g2" style="margin-top:14px"><div class="card"><div class="row"><h3>Learning profile</h3><button class="btn" id="anProf">Update with AI</button></div><div class="list" style="margin-top:8px">'+[['Schedule','Observed focus windows.'],['Pace','Reading/video speed and session duration.'],['Engagement','Active vs idle behavior.'],['Understanding','Quiz and teach-back evidence.'],['Retention','Performance over time and spaced reviews.'],['Preference','PDF/video/audio/practice.'],['Motivation','Healthy continuation signals.'],['Weaknesses',m.slice(0,5).map(x=>x.concepts?.title||'Concept').join(', ')||'None yet'],['Collaboration','Room participation patterns.']].map(x=>'<div class="list-item"><div class="list-main"><strong>'+esc(x[0])+'</strong><small>'+esc(x[1])+'</small></div></div>').join('')+'</div></div><div class="card"><div class="row"><h3>Mastery map</h3><span class="pill blue">Estimate</span></div><div class="list" style="margin-top:8px">'+(m.map(x=>'<div class="list-item"><div class="ring" style="--p:'+Math.round(x.mastery||0)+'%"><b>'+Math.round(x.mastery||0)+'%</b></div><div class="list-main"><strong>'+esc(x.concepts?.title||'Concept')+'</strong><small>Exposure '+Math.round(x.exposure||0)+' · Understand '+Math.round(x.understanding||0)+' · Recall '+Math.round(x.recall||0)+' · Apply '+Math.round(x.application||0)+'</small></div></div>').join('')||'<div class="empty">Practice will populate mastery.</div>')+'</div></div></div><div class="card" style="margin-top:14px"><div class="row"><h3>Weekly report</h3><button class="btn" id="exReport">Export</button></div><div class="grid g4" style="margin-top:10px"><div class="card soft"><div class="eyebrow">Focus</div><strong>'+fmtMinutes(focus)+'</strong></div><div class="card soft"><div class="eyebrow">Questions</div><strong>'+qz.length+'</strong></div><div class="card soft"><div class="eyebrow">Mastery</div><strong>'+avgM+'%</strong></div><div class="card soft"><div class="eyebrow">Suggestion</div><strong class="small">Review difficult concepts within 48h.</strong></div></div></div>';$('anProf').onclick=analyzeProfile;$('exReport').onclick=()=>{const text='# Lucid Weekly Report\\n\\nFocused study: '+fmtMinutes(focus)+'\\nPages touched: '+new Set(e.filter(x=>x.event_type==='page_entered').map(x=>x.resource_id+'-'+x.payload?.page)).size+'\\nQuestions: '+qz.length+'\\nAverage recall: '+avg+'%\\nAverage mastery: '+avgM+'%\\nActive days: '+days+'/7';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown'}));a.download='lucid-weekly-report.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}}
