   try{const r=await fetch(C.SUPABASE_URL+'/functions/v1/youtube-import',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+sess.access_token,'apikey':C.SUPABASE_KEY},body:JSON.stringify({url:state.current.source_url})});if(r.ok)meta=await r.json()}catch(e){}
